function UIMazeBagItemsNode:Refresh(data, clickCb)
    if not data then
        return
    end
    self._data = data
    self._clickCb = clickCb

    self:Fillitems()
end

function UIMazeBagItemsNode:Fillitems()
    for i = 1, #self._data do
        local itemCell = self:GetItemNode(i)
        if itemCell then 
            local scr = CfUtils.GetLuaScr(itemCell, UIMazeBagItemNode)
            if scr then
                scr:Refresh(self._data[i], function(go, id)
                    if self._clickCb then
                        self._clickCb(go, id)
                    end
                end)
            end
        end

        KTool.SetActive(itemCell, true)
    end
    
    if #self._data < 4 then
        for i = #self._data + 1, 4 do
            local itemGoPar = self:GetItemNode(i)
            if itemGoPar then
                KTool.SetActive(itemGoPar, false)
            end
        end
    end
end

function UIMazeBagItemsNode:GetItemNode(ind)
    ind = checkNumber(ind)
    if ind == 1 then
        return self.item1
    elseif ind == 2 then
        return self.item2
    elseif ind == 3 then
        return self.item3
    elseif ind == 4 then
        return self.item4
    end
    return nil
end

